{{-- P7-1: one position of a card's badges (closed class words: the colour pair, the shape and the background opacity are validated; the text is escaped, never markup; no style, no script). The classes are `sf-cbadge*`: `.sf-badge` is the menu's label. --}}<ul class="sf-cbadges sf-cbadges--{{ str_replace('_', '-', $position) }}">@foreach ($badges as $badge)<li class="sf-cbadge sf-cbadge--{{ $badge->style }} sf-cbadge--{{ $badge->shape }} sf-cbadge--o{{ $badge->opacity }}">{{ $badge->label }}</li>@endforeach</ul>